-- services
insert into public.services (id, status, sort_order, slug, title, tagline, icon, summary, problem, audience, included, approach, deliverables, faqs, cta_label)
values ('00000000-0000-4000-8000-000000000101', 'published', 1, 'beverage-consulting', 'Beverage Consulting', 'Menus, programs and beverage strategy.', 'wine', 'Beverage concepts, menus and programs that guests remember - and that make commercial sense.', 'Menus that don''t sell, inconsistent drinks, rising costs or a concept that doesn''t match the venue. Beverage is often a venue''s highest-margin category, yet it is rarely managed with the same rigour as the kitchen.', 'Hotels, restaurants, bars, cafés and resorts launching or relaunching a beverage offer, and groups that want consistency across outlets.', array['Beverage concept development', 'Menu development and optimization', 'Coffee and bar programs', 'Product and supplier selection', 'Costing, pricing and profitability', 'Beverage program audits', 'Launch / pre-opening beverage support']::text[], 'Anthony starts with an on-site assessment of the venue, guests, team and numbers, then builds the concept and menu with the team rather than for it - so it can be executed every shift.', array['Beverage concept and positioning', 'Menu structure, specs and costings', 'Supplier and product recommendations', 'Audit report with prioritised actions', 'Launch plan and team briefing']::text[], '[{"question":"Do you work with existing menus or only new concepts?","answer":"Both. Many projects start with an audit of an existing menu, followed by targeted changes."},{"question":"Will we own the recipes and specs?","answer":"Yes - deliverables created for your venue are handed over to your team."}]'::jsonb, 'Discuss your beverage program')
on conflict do nothing;

insert into public.services (id, status, sort_order, slug, title, tagline, icon, summary, problem, audience, included, approach, deliverables, faqs, cta_label)
values ('00000000-0000-4000-8000-000000000102', 'published', 2, 'operations-consulting', 'Operations Consulting', 'Systems, efficiency and profitable growth.', 'settings', 'Workflows, SOPs and controls that make great service repeatable and protect your margins.', 'Slow service, waste, unclear roles, stock that doesn''t add up and standards that depend on who is working that day.', 'Operators preparing to open, venues that are growing quickly, and established businesses that need tighter control.', array['Operational assessment', 'Workflow and service optimization', 'SOP development', 'Inventory and cost-control systems', 'Team structure and role clarity', 'Guest journey improvement', 'Pre-opening / opening support']::text[], 'Observe service, map the workflow, find the bottlenecks, then design simple systems the team will actually use - and stay through implementation.', array['Operational assessment report', 'SOP and checklist library', 'Inventory and cost-control templates', 'Organisation chart and role descriptions', 'Opening timeline and critical path']::text[], '[{"question":"How long does an operational assessment take?","answer":"Typically a few days on-site depending on the size of the operation, followed by a written report."}]'::jsonb, 'Improve your operation')
on conflict do nothing;

insert into public.services (id, status, sort_order, slug, title, tagline, icon, summary, problem, audience, included, approach, deliverables, faqs, cta_label)
values ('00000000-0000-4000-8000-000000000103', 'published', 3, 'training-team-development', 'Training & Team Development', 'Skills, mindset and high-performing teams.', 'users', 'Practical training that builds skill, confidence and consistency - from the espresso machine to leadership.', 'High turnover, inconsistent standards, missed upselling opportunities and supervisors promoted without leadership support.', 'Barista and bar teams, service teams, supervisors and managers - as one-off sessions or ongoing programs.', array['Barista training', 'Bartender / mixology training', 'Product knowledge', 'Service standards', 'Upselling and sales behavior', 'Workflow and speed', 'Leadership and team development', 'Custom corporate training']::text[], 'Hands-on sessions built around your menu and your service, with practical assessments and follow-up so the training sticks.', array['Training needs assessment', 'Custom training modules and manuals', 'Practical assessments and certificates', 'Follow-up coaching sessions']::text[], '[{"question":"Can training be delivered on-site?","answer":"Yes. Most programs are delivered at your venue using your equipment and menu."},{"question":"Do you train in groups or one-to-one?","answer":"Both - from small teams to group-wide programs."}]'::jsonb, 'Request training')
on conflict do nothing;

